		spell_tier = "神圣级天惠白核"
		magnitude_desc = "35,000 绝对护盾"
	else:
		spell_name = "双魔调和·辉光暗影连环爆裂 (Dualcast Light & Shadow Burst)"
		spell_tier = "高阶战术禁术"
		magnitude_desc = "39,200 连击总效"
		
